const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sources=[],page='home',kind='plan',tab='exam',slideIndex=0,current=null,saved=[];let draft={title:'Nước Mỹ và Tây Âu từ năm 1945 đến năm 1991',subject:'Lịch sử',grade:'9',book:'Kết nối tri thức với cuộc sống',teacher:'',school:'',periods:'2',minutes:'45',goals:'Trình bày được những nét chính về nước Mỹ và Tây Âu từ năm 1945 đến năm 1991.\nGiải thích sự phát triển kinh tế và quá trình liên kết ở Tây Âu.',content:'Nước Mỹ: tình hình chính trị, kinh tế sau năm 1945; chính sách đối ngoại.\nTây Âu: quá trình phục hồi kinh tế sau chiến tranh; sự liên kết khu vực.',digital:true,ai:false,defense:false,source:''};
try{saved=JSON.parse(localStorage.getItem('ga-saved')||'[]');draft={...draft,...JSON.parse(localStorage.getItem('ga-draft')||'{}')};current=JSON.parse(localStorage.getItem('ga-current')||'null')}catch(e){}
const names={home:'Tổng quan',plan:'Kế hoạch bài dạy',slides:'Slide bài giảng',exam:'Bài kiểm tra',library:'Học liệu của bạn',saved:'Đã lưu & xuất bản',guide:'Căn cứ & hướng dẫn'};const types={mc:'Nhiều lựa chọn',tf:'Đúng – Sai',short:'Trả lời ngắn',essay:'Tự luận'},levels=['Biết','Hiểu','Vận dụng'];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){try{localStorage.setItem('ga-draft',JSON.stringify(draft));localStorage.setItem('ga-current',JSON.stringify(current));localStorage.setItem('ga-saved',JSON.stringify(saved))}catch(e){toast('Bộ nhớ trình duyệt đầy. Hãy tải bản sao JSON.')}}
function heading(eyebrow,title,sub,action=''){return `<div class="headrow"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function go(p){page=names[p]?p:'home';if(['plan','slides','exam'].includes(page))kind=page;render();location.hash=page;window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();go(b.dataset.page)}});
function render(){document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#breadcrumb').innerHTML=`Không gian làm việc <span>/</span> ${names[page]}`;$('#app').innerHTML=page==='home'?home():['plan','slides','exam'].includes(page)?editor():page==='library'?library():page==='saved'?savedView():guide();if(['plan','slides','exam'].includes(page))bindForm();if(page==='library')bindLibrary()}
function home(){return heading('MỖI BÀI DẠY, MỘT HÀNH TRÌNH','Sẵn sàng cho tiết học tiếp theo?','Một không gian để biến học liệu thành những bài dạy có ý nghĩa.',`<button class="primary" data-page="plan">＋ Soạn bài mới</button>`)+`<section class="hero history-hero"><img class="history-cover" src="assets/lich-su-viet-nam.png" alt="Tranh minh họa một vị tướng cưỡi ngựa cùng đoàn quân và cờ ngũ sắc"><div class="history-shade"></div><div class="hero-copy"><span class="eyebrow">KHÔNG GIAN SOẠN GIẢNG LỊCH SỬ</span><h2>Đánh thức quá khứ.<br>Truyền cảm hứng tương lai.</h2><p>Từ những câu chuyện lịch sử đến tiết học đầy khám phá. Chuẩn bị giáo án, bài giảng và đánh giá trong cùng một không gian.</p><div class="history-actions"><button class="primary" data-page="plan">＋ Bắt đầu soạn bài</button><button class="secondary" data-page="library">Khám phá học liệu ↗</button></div></div><div class="history-caption">HỌC LỊCH SỬ · HIỂU CỘI NGUỒN</div></section><div class="sectionrow"><h2>Bạn muốn tạo gì hôm nay?</h2><span>3 công cụ · 1 quy trình soạn giảng</span></div><div class="cards">${[['plan','▤','Kế hoạch bài dạy','Từ yêu cầu cần đạt đến hoạt động học tập, sản phẩm và đánh giá.','Khung Công văn 5512'],['slides','▧','Slide bài giảng','Biến nội dung thành bài giảng trực quan, sẵn sàng lên lớp.','Xuất PowerPoint'],['exam','☷','Bài kiểm tra','Liên kết câu hỏi với ma trận, đặc tả và hướng dẫn chấm.','Tham khảo Công văn 7991']].map(([p,i,t,d,b])=>`<button class="create-card" data-page="${p}"><span class="iconbox">${i}</span><h3>${t}</h3><p>${d}</p><div class="card-bottom"><span>${b}</span><span class="arrow">↗</span></div></button>`).join('')}</div><div class="sectionrow"><h2>Học liệu sẵn sàng sử dụng</h2><button data-page="library" style="font-size:11px;color:var(--green)">Xem tất cả ${sources.length} học liệu →</button></div><div class="tablewrap"><table><thead><tr><th>TÊN HỌC LIỆU</th><th>LOẠI</th><th>KHỐI</th><th></th></tr></thead><tbody>${[...sources.filter(x=>x.type==='Slide'),...sources.filter(x=>x.type==='Ngân hàng câu hỏi'),...sources.filter(x=>x.name.includes('BÀI 11'))].slice(0,4).map(s=>`<tr><td class="filename"><span class="fileicon">${s.type==='Slide'?'▧':'▤'}</span>${esc(s.name.replace(/\.(docx?|ppt)$/i,''))}</td><td>${s.type}</td><td><span class="tag">Lớp ${s.grade}</span></td><td><button onclick="viewSource(${sources.indexOf(s)})">Mở ↗</button></td></tr>`).join('')}</tbody></table></div><div class="notice"><span>ⓘ</span><div><b>Đúng căn cứ, linh hoạt theo thực tế</b><br>7991 hướng dẫn kiểm tra, đánh giá. Giáo án dùng khung 5512; slide phục vụ hoạt động học tập. Tỉ lệ đề THCS cần đối chiếu hướng dẫn của Sở/trường.</div></div>`}
function field(key,label,type='text',options=null){return `<div class="field"><label for="${key}">${label}</label>${options?`<select id="${key}" data-field="${key}">${options.map(v=>`<option ${String(draft[key])===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${key}" data-field="${key}">${esc(draft[key])}</textarea>`:`<input id="${key}" data-field="${key}" type="${type}" ${type==='number'?'min="1" max="180"':''} value="${esc(draft[key])}">`}</div>`}
function editor(){const isCurrent=current&&current.kind===kind;return heading('KHÔNG GIAN SOẠN GIẢNG',names[kind],kind==='exam'?'Xây dựng đề từ câu hỏi thực tế. Ma trận tự cập nhật theo điểm.':'Tạo bản nháp từ nội dung của bạn, rồi chỉnh sửa trước khi xuất.')+`<div class="editor-grid"><section class="panel"><div class="panel-title">01 / Thông tin & nội dung</div>${kind==='exam'?'<button class="secondary" style="margin-bottom:15px;width:100%" onclick="loadExampleExam()">Tải đề minh họa Bài 11 · 10 điểm</button>':''}${field('title',kind==='exam'?'Tên bài kiểm tra':'Tên bài học')}${field('subject','Môn học','text',['Lịch sử','Địa lí','Toán','Ngữ văn','Vật lí','Hóa học','Sinh học','Tin học','Giáo dục công dân','Khác'])}<div class="fieldrow">${field('grade','Khối lớp','text',['6','7','8','9','10','11','12'])}${field(kind==='exam'?'minutes':'periods',kind==='exam'?'Thời gian (phút)':'Số tiết','number')}</div>${field('book','Bộ sách')}${field('school','Trường')}${field('teacher','Giáo viên')}<div class="field"><label for="source">Học liệu tham khảo</label><select id="source" onchange="draft.source=this.value;persist()"><option value="">Chọn từ học liệu của bạn</option>${sources.map((s,i)=>`<option value="${i}" ${draft.source===String(i)?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="secondary" style="margin-top:8px;padding:5px 9px" onclick="applySource()">↓ Đưa vào nội dung</button></div>${field('goals','Yêu cầu cần đạt (mỗi dòng một ý)','textarea')}${field('content','Nội dung kiến thức / tư liệu','textarea')}${kind!=='exam'?`<div class="panel-title">02 / Tích hợp vào hoạt động</div>${[['digital','Năng lực số'],['ai','Sử dụng AI có kiểm chứng'],['defense','Giáo dục quốc phòng – an ninh']].map(([k,t])=>`<label class="check"><input type="checkbox" data-field="${k}" ${draft[k]?'checked':''}>${t}</label>`).join('')}`:`<div class="notice" style="padding:10px;margin-bottom:14px">Mẫu tham khảo: 30% nhiều lựa chọn, 20% đúng/sai, 20% trả lời ngắn, 30% tự luận. Không dùng trả lời ngắn: chuyển 20% sang đúng/sai.</div>`}<button class="primary" style="width:100%;justify-content:center" onclick="generate()">✧ Tạo bản nháp ${kind==='slides'?'bài giảng':kind==='exam'?'đề kiểm tra':'kế hoạch'}</button><p class="help" style="margin-top:10px">Tạo bằng khung mẫu và nội dung đầu vào. Chưa kết nối mô hình AI; cần duyệt nội dung chuyên môn.</p></section><section><div class="toolbar"><button class="secondary" onclick="saveCurrent()">▱ Lưu bản nháp</button>${kind==='slides'?'<button class="secondary" onclick="exportPptx()">↓ PowerPoint</button>':'<button class="secondary" onclick="exportWord()">↓ Word</button>'}<button class="secondary" onclick="printCurrent()">↓ PDF / In</button><button class="primary" onclick="publishCurrent()">↗ Xuất bản HTML</button></div><div class="preview-label"><span>02 / XEM TRƯỚC & CHỈNH SỬA</span><span>${isCurrent?'Nhấn vào nội dung để sửa':'Chưa tạo bản nháp'}</span></div><div id="preview">${isCurrent?preview():`<div class="document empty"><span class="iconbox" style="margin:50px auto 20px">${kind==='slides'?'▧':kind==='exam'?'☷':'▤'}</span><h2 style="font:24px Georgia">Bài dạy của bạn bắt đầu từ đây.</h2><p style="font:12px 'Segoe UI';margin-top:15px">Điền thông tin bên trái hoặc chọn học liệu có sẵn,<br>sau đó nhấn “Tạo bản nháp”.</p></div>`}</div></section></div>`}
function bindForm(){document.querySelectorAll('[data-field]').forEach(x=>x.addEventListener('input',()=>{draft[x.dataset.field]=x.type==='checkbox'?x.checked:x.value;persist()}))}
function applySource(){const s=sources[Number(draft.source)];if(draft.source===''||!s){toast('Chọn học liệu trước.');return}draft.content=s.text;draft.grade=s.grade;const m=s.text.match(/BÀI\s*\d+\s*[:：]\s*([^\n]+)/i);if(m)draft.title=m[1].trim();const g=s.text.match(/(?:I\.\s*MỤC TIÊU[\s\S]*?)(?=II\.)/i);if(g)draft.goals=g[0].slice(0,3500);persist();render();toast('Đã đưa nội dung nguồn vào biểu mẫu.');}
function paragraphs(t){return t.split(/\n+/).map(x=>x.trim()).filter(Boolean)}
function extractFacts(t){return paragraphs(t).filter(x=>x.length>35&&x.length<500&&!/^GIÁO ÁN|^BÀI |^CHƯƠNG|^I{1,3}\. |^Mục tiêu|^Kỹ thuật|^Bước|^Hoạt động|^GV |^HS |^Quy định/.test(x)).slice(0,24)}
function activity(title,time,objective,task,product){return {title: title+' ('+time+' phút)',text:`a) Mục tiêu: ${objective}\nb) Nội dung: ${task}\nc) Sản phẩm: ${product}\nd) Tổ chức thực hiện:\n• Chuyển giao: Giáo viên nêu nhiệm vụ, tiêu chí đánh giá và thời gian thực hiện.\n• Thực hiện: Học sinh làm việc cá nhân/nhóm, khai thác học liệu; giáo viên quan sát và hỗ trợ.\n• Báo cáo, thảo luận: Đại diện trình bày sản phẩm; học sinh khác nhận xét, bổ sung bằng dẫn chứng.\n• Kết luận, nhận định: Giáo viên đối chiếu yêu cầu cần đạt, phản hồi và chốt nội dung đã được kiểm chứng.`}}
function generate(){if(!draft.title.trim()||!draft.content.trim()||!draft.goals.trim()){toast('Điền tên bài, yêu cầu cần đạt và nội dung kiến thức.');return}if(current&&current.kind===kind&&!confirm('Tạo lại sẽ thay nội dung bản nháp hiện tại. Bạn đã lưu các chỉnh sửa cần giữ chưa?'))return;const facts=extractFacts(draft.content),goals=paragraphs(draft.goals);current={id:crypto.randomUUID(),kind,meta:{...draft},created:new Date().toISOString(),status:'Bản nháp',sourceName:draft.source!==''?sources[Number(draft.source)]?.name:'Nội dung giáo viên nhập'};
if(kind==='plan'){const total=Number(draft.periods)*45;const practice=Math.max(8,Math.round(total*.17)),opening=5,application=5,knowledge=total-practice-opening-application;current.sections=[{title:'I. MỤC TIÊU',text:`1. Yêu cầu cần đạt\n${goals.join('\n')}\n2. Năng lực\nTự chủ và tự học; giao tiếp và hợp tác; giải quyết vấn đề. Năng lực môn ${draft.subject}: khai thác học liệu, trình bày, giải thích và vận dụng nội dung bài học.\n3. Phẩm chất\nChăm chỉ trong thực hiện nhiệm vụ; trung thực khi sử dụng thông tin; trách nhiệm với sản phẩm nhóm.`},{title:'II. THIẾT BỊ DẠY HỌC VÀ HỌC LIỆU',text:`Giáo viên: SGK ${draft.book}, máy chiếu, phiếu học tập và bảng tiêu chí đánh giá.\nHọc sinh: SGK, vở ghi, đọc trước nội dung ${draft.title}.\nHọc liệu tham khảo: ${current.sourceName}.`},{title:'III. TIẾN TRÌNH DẠY HỌC',text:`Thời lượng dự kiến: ${total} phút / ${draft.periods} tiết. Điều chỉnh phân tiết theo kế hoạch của nhà trường.`},activity('1. Mở đầu',opening,'Kết nối hiểu biết đã có với vấn đề của bài học.',`Quan sát tư liệu hoặc tình huống liên quan đến “${draft.title}”; nêu hai điều đã biết và một điều muốn tìm hiểu.`,'Câu trả lời ban đầu và câu hỏi học tập.'),activity('2. Hình thành kiến thức',knowledge,goals.join('; '),`Đọc tư liệu và SGK, thực hiện phiếu học tập theo các đơn vị kiến thức:\n${(facts.length?facts:paragraphs(draft.content)).slice(0,12).join('\n')}\nMỗi nhóm lựa chọn dẫn chứng để giải thích kết quả.`,'Bảng tổng hợp kiến thức; dẫn chứng có nguồn; câu trả lời gắn với yêu cầu cần đạt.'),activity('3. Luyện tập',practice,'Củng cố kiến thức và kiểm tra mức độ hiểu.',`Hoàn thành sơ đồ hệ thống hóa “${draft.title}”; trả lời câu hỏi về các khái niệm, sự kiện hoặc quan hệ chính; đổi phiếu để nhận xét.`,'Sơ đồ/bảng tổng hợp và phiếu trả lời; sửa những nội dung chưa chính xác.'),activity('4. Vận dụng',application,'Vận dụng kiến thức vào tình huống phù hợp.',`Lựa chọn một vấn đề liên quan đến “${draft.title}”; viết một đoạn giải thích hoặc thiết kế sản phẩm ngắn kèm dẫn chứng. Hoàn thiện ở nhà nếu cần.`,'Sản phẩm vận dụng có lập luận và nguồn tham khảo.'),{title:'IV. ĐÁNH GIÁ VÀ ĐIỀU CHỈNH',text:'Tiêu chí: chính xác về kiến thức; dẫn chứng phù hợp; trình bày rõ ràng; hợp tác và hoàn thành nhiệm vụ.\nCông cụ: quan sát, phiếu học tập, câu trả lời và sản phẩm vận dụng.\nĐiều chỉnh sau bài dạy: giáo viên bổ sung sau khi thực hiện.'}];let integration=[];if(draft.digital)integration.push('Năng lực số: học sinh so sánh hai nguồn tư liệu do giáo viên cung cấp, chỉ ra tác giả, thời điểm và căn cứ tin cậy; lập bảng tổng hợp thông tin. Đánh giá bằng phiếu đối chiếu nguồn.');if(draft.ai)integration.push('AI: giáo viên cung cấp một đoạn trả lời do AI tạo về nội dung bài; học sinh đối chiếu với SGK và đánh dấu thông tin đúng/chưa có căn cứ. Không dùng kết quả AI làm đáp án mặc định.');if(draft.defense)integration.push('Quốc phòng – an ninh: giáo viên chọn tình huống liên hệ về chủ quyền, hòa bình hoặc trách nhiệm công dân phù hợp nội dung; học sinh nêu hành vi có trách nhiệm.');if(integration.length)current.sections.push({title:'V. HOẠT ĐỘNG TÍCH HỢP',text:integration.join('\n')});}
if(kind==='slides'){current.slides=[{title:draft.title,text:`${draft.subject} ${draft.grade} · ${draft.book}`,note:'Giới thiệu chủ đề và định hướng bài học.'},{title:'Hôm nay, chúng ta sẽ…',text:goals.slice(0,5).join('\n'),note:'Giới thiệu yêu cầu cần đạt.'},{title:'Khởi động: kết nối điều đã biết',text:`Bạn đã biết điều gì về ${draft.title}?\nHãy nêu một câu hỏi bạn muốn tìm hiểu.`,note:'Cho học sinh suy nghĩ 1 phút, mời 2–3 học sinh chia sẻ.'},...Array.from({length:Math.max(1,Math.ceil(Math.min(facts.length,18)/3))},(_,i)=>({title:'Khám phá kiến thức '+(i+1),text:(facts.length?facts.slice(i*3,i*3+3):paragraphs(draft.content).slice(0,3)).join('\n'),note:'Đối chiếu SGK, thảo luận và trình bày dẫn chứng; giáo viên chốt nội dung.'})),{title:'Thảo luận & hệ thống hóa',text:'Lập bảng: nội dung chính – dẫn chứng – ý nghĩa.\nSo sánh kết quả với nhóm khác.\nGiải thích một mối liên hệ bạn tìm được.',note:'Chia nhóm 4 học sinh. Quan sát và hỗ trợ nhóm còn khó khăn.'},{title:'Luyện tập',text:goals.slice(0,3).map((g,i)=>`${i+1}. Hãy thực hiện yêu cầu: ${g}`).join('\n'),note:'Kiểm tra cá nhân, phản hồi theo yêu cầu cần đạt.'},{title:'Vận dụng & hẹn gặp lại',text:`Chọn một vấn đề liên quan đến ${draft.title}.\nViết đoạn giải thích ngắn, có dẫn chứng và nguồn.\nĐọc trước nội dung tiết học tiếp theo.`,note:'Nêu tiêu chí sản phẩm, thời hạn và cách nộp.'}];slideIndex=0;}
if(kind==='exam'){current.questions=[];current.targets={mc:30,tf:40,short:0,essay:30,know:40,understand:30,apply:30};let selectedSource=draft.source!==''?sources[Number(draft.source)]:null;const imported=parseQuestions(selectedSource?.text||draft.content);if(imported.length)current.questions=imported.slice(0,12);else{current.questions=[{id:crypto.randomUUID(),type:'essay',level:'Biết',topic:draft.title,goal:goals[0],text:`Trình bày những nội dung chính của ${draft.title}.`,options:'',answer:'',points:4},{id:crypto.randomUUID(),type:'essay',level:'Hiểu',topic:draft.title,goal:goals[1]||goals[0],text:`Giải thích một mối quan hệ hoặc nguyên nhân quan trọng trong nội dung ${draft.title}. Nêu dẫn chứng.`,options:'',answer:'',points:3},{id:crypto.randomUUID(),type:'essay',level:'Vận dụng',topic:draft.title,goal:goals[goals.length-1],text:`Từ nội dung ${draft.title}, rút ra một bài học có thể vận dụng vào thực tế và giải thích lựa chọn của em.`,options:'',answer:'',points:3}];}tab='exam';}
persist();render();toast('Đã tạo bản nháp. Hãy kiểm tra và chỉnh sửa trước khi xuất.');}
function parseQuestions(t){let chunks=t.split(/(?:^|\n)\s*Câu\s*\d+\s*[.:]/i).slice(1);return chunks.map(c=>{let m=c.match(/([\s\S]*?)(?:^|\n|\s{2,})A[.：:]\s*([\s\S]*?)B[.：:]\s*([\s\S]*?)C[.：:]\s*([\s\S]*?)D[.：:]\s*([^\n]*(?:\n(?![ABCD][.：:])[^\n]*)?)/);if(!m)return null;return {id:crypto.randomUUID(),type:'mc',level:'Biết',topic:draft.title,goal:'Giáo viên xác định yêu cầu cần đạt tương ứng.',text:m[1].trim(),options:m.slice(2,6).map((s,i)=>'ABCD'[i]+'. '+s.trim()).join('\n'),answer:'',points:.25}}).filter(Boolean)}
function metaHtml(){const m=current.meta;return `<h2>${esc(m.title)}</h2><div class="meta">${esc(m.subject)} ${esc(m.grade)} · ${esc(m.book)}<br>${esc(m.school)}${m.teacher?' · Giáo viên: '+esc(m.teacher):''}</div>`}
function preview(){return current.kind==='plan'?`<div class="document">${metaHtml()}${current.sections.map((s,i)=>`<h3 contenteditable="true" oninput="editSection(${i},'title',this.innerText)">${esc(s.title)}</h3><div contenteditable="true" style="white-space:pre-wrap;font:14px/1.75 'Times New Roman'" oninput="editSection(${i},'text',this.innerText)">${esc(s.text)}</div>`).join('')}</div>`:current.kind==='slides'?slidesView():examView()}
function editSection(i,k,v){current.sections[i][k]=v;persist()}
function slidesView(){let s=current.slides[slideIndex];return `<div class="slide-list">${current.slides.map((x,i)=>`<button class="${i===slideIndex?'active':''}" onclick="slideTo(${i})">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="slide"><div class="slide-kicker">${esc(current.meta.subject.toUpperCase())} ${esc(current.meta.grade)} · BÀI GIẢNG</div><h2>${esc(s.title)}</h2><ul>${paragraphs(s.text).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="slide-num">${slideIndex+1} / ${current.slides.length}</div></div><div class="slide-control"><button class="secondary" onclick="slideTo(${Math.max(0,slideIndex-1)})">← Trước</button><button onclick="present()">▶ Trình chiếu</button><button class="secondary" onclick="slideTo(${Math.min(current.slides.length-1,slideIndex+1)})">Tiếp →</button></div><div class="panel" style="margin-top:20px"><div class="panel-title">Chỉnh sửa slide ${slideIndex+1}</div><div class="field"><label>Tiêu đề</label><input value="${esc(s.title)}" oninput="editSlide('title',this.value)"></div><div class="field"><label>Nội dung (mỗi dòng một ý)</label><textarea oninput="editSlide('text',this.value)">${esc(s.text)}</textarea></div><div class="field"><label>Ghi chú giảng dạy</label><textarea oninput="editSlide('note',this.value)">${esc(s.note)}</textarea></div><button class="secondary" onclick="addSlide()">＋ Thêm slide</button> <button class="secondary" onclick="removeSlide()">Xóa slide này</button></div>`}
function slideTo(i){slideIndex=i;$('#preview').innerHTML=slidesView()}
function editSlide(k,v){current.slides[slideIndex][k]=v;persist();const s=current.slides[slideIndex];$('.slide h2').textContent=s.title;$('.slide ul').innerHTML=paragraphs(s.text).map(x=>`<li>${esc(x)}</li>`).join('')}
function addSlide(){current.slides.push({title:'Tiêu đề mới',text:'Nội dung bài giảng',note:''});persist();slideTo(current.slides.length-1)}function removeSlide(){if(current.slides.length===1)return toast('Giữ lại ít nhất một slide.');current.slides.splice(slideIndex,1);persist();slideTo(Math.min(slideIndex,current.slides.length-1))}
function present(){let i=slideIndex;const el=document.createElement('div');el.className='presentation';function draw(){let s=current.slides[i];el.innerHTML=`<div class="slide"><div class="slide-kicker">${esc(current.meta.subject)} ${esc(current.meta.grade)}</div><h2>${esc(s.title)}</h2><ul>${paragraphs(s.text).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="slide-num">${i+1} / ${current.slides.length}</div></div><div class="presentation-tools"><button id="prev">←</button><span>Phím ← → · Esc để thoát</span><button id="next">→</button><button id="exit">Đóng ×</button></div>`;el.querySelector('#prev').onclick=()=>{i=Math.max(0,i-1);draw()};el.querySelector('#next').onclick=()=>{i=Math.min(current.slides.length-1,i+1);draw()};el.querySelector('#exit').onclick=close;}function close(){el.remove();document.removeEventListener('keydown',keys)}function keys(e){if(e.key==='Escape')close();if(e.key==='ArrowRight'){i=Math.min(current.slides.length-1,i+1);draw()}if(e.key==='ArrowLeft'){i=Math.max(0,i-1);draw()}}draw();document.body.append(el);document.addEventListener('keydown',keys)}
function sums(){const q=current.questions,total=q.reduce((s,x)=>s+Number(x.points||0),0),byType=Object.fromEntries(Object.keys(types).map(t=>[t,q.filter(x=>x.type===t).reduce((s,x)=>s+Number(x.points||0),0)])),byLevel=Object.fromEntries(levels.map(t=>[t,q.filter(x=>x.level===t).reduce((s,x)=>s+Number(x.points||0),0)]));return {total,byType,byLevel}}
function checks(){const s=sums(),q=current.questions,w=[];if(Math.abs(s.total-10)>.001)w.push(`Tổng điểm ${s.total.toFixed(2)} / 10.`);if(['mc','tf','short','essay'].reduce((a,k)=>a+current.targets[k],0)!==100||['know','understand','apply'].reduce((a,k)=>a+current.targets[k],0)!==100)w.push('Tổng tỉ lệ mục tiêu của mỗi nhóm phải bằng 100%.');if(q.some(x=>!x.answer.trim()))w.push('Có câu chưa nhập đáp án/hướng dẫn chấm.');if(q.some(x=>!x.text.trim()||!x.goal.trim()))w.push('Có câu thiếu nội dung hoặc yêu cầu cần đạt.');if(q.some(x=>x.type==='tf'&&paragraphs(x.options).length!==4))w.push('Câu đúng/sai phải có 4 ý.');if(q.some(x=>x.type==='mc'&&paragraphs(x.options).length!==4))w.push('Câu nhiều lựa chọn phải có 4 phương án.');if(s.total>0){Object.keys(types).forEach(t=>{if(Math.abs(s.byType[t]/s.total*100-current.targets[t])>1)w.push(`${types[t]}: ${(s.byType[t]/s.total*100).toFixed(1)}%, mục tiêu ${current.targets[t]}%.`)});levels.forEach((l,i)=>{const target=current.targets[['know','understand','apply'][i]];if(Math.abs(s.byLevel[l]/s.total*100-target)>1)w.push(`${l}: ${(s.byLevel[l]/s.total*100).toFixed(1)}%, mục tiêu ${target}%.`)})}return w}
function examView(){const s=sums(),w=checks();return `<div class="tabs">${[['exam','Đề kiểm tra'],['matrix','Ma trận'],['spec','Bản đặc tả'],['answers','Hướng dẫn chấm'],['questions','Sửa câu hỏi'],['rules','Cấu hình']].map(([k,t])=>`<button class="${tab===k?'active':''}" onclick="examTab('${k}')">${t}</button>`).join('')}</div><div class="stats"><div class="stat"><strong>${current.questions.length}</strong>Câu hỏi</div><div class="stat"><strong>${s.total.toFixed(2)} / 10</strong>Tổng điểm</div><div class="stat"><strong>${w.length?w.length+' mục':'Đã khớp'}</strong>Cần rà soát</div></div>${w.length?`<details class="notice" style="display:block;margin:0 0 15px"><summary>${w.length} mục cần rà soát trước khi sử dụng</summary><ul>${w.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:'<div class="notice" style="margin:0 0 15px">✓ Điểm và cơ cấu khớp cấu hình. Giáo viên vẫn cần duyệt nội dung và mức độ nhận thức.</div>'}${tab==='questions'?questionEditor():tab==='rules'?rulesEditor():`<div class="document">${metaHtml()}${tab==='exam'?examHtml(false):tab==='matrix'?matrixHtml():tab==='spec'?specHtml():answersHtml()}</div>`}`}
function examTab(t){tab=t;$('#preview').innerHTML=examView()}
function examHtml(includeAnswers=false){let n=0;return `<p style="text-align:center">Thời gian: ${esc(current.meta.minutes)} phút · Thang điểm: 10<br>Họ và tên: ................................................... Lớp: ............</p>${Object.keys(types).map((t,i)=>{const qs=current.questions.filter(x=>x.type===t);if(!qs.length)return '';return `<h3>PHẦN ${i+1}. ${types[t].toUpperCase()} (${qs.reduce((a,x)=>a+Number(x.points),0).toFixed(2)} điểm)</h3>${qs.map(q=>`<p><b>Câu ${++n} (${Number(q.points).toFixed(2)} điểm).</b> ${esc(q.text)}</p>${q.options?`<div style="white-space:pre-wrap;font:14px/1.75 'Times New Roman'">${esc(q.options)}</div>`:''}${t==='essay'?'<p>........................................................................................<br>........................................................................................</p>':''}`).join('')}`}).join('')}${includeAnswers?answersHtml():''}`}
function orderedQuestions(){return Object.keys(types).flatMap(t=>current.questions.filter(q=>q.type===t))}
function matrixRows(){const topics=[...new Set(current.questions.map(x=>x.topic||current.meta.title))];return topics.map(topic=>{const qs=orderedQuestions().map((q,i)=>({...q,num:i+1})).filter(q=>(q.topic||current.meta.title)===topic);return {topic,cells:Object.keys(types).flatMap(t=>levels.map(l=>{const a=qs.filter(q=>q.type===t&&q.level===l);return a.map(q=>'C'+q.num).join(', ')+(a.length?` (${a.reduce((s,q)=>s+Number(q.points),0).toFixed(2)}đ)`:'')})),total:qs.reduce((s,q)=>s+Number(q.points),0)}})}
function matrixHtml(){let rows=matrixRows();return `<h3>MA TRẬN ĐỀ KIỂM TRA ĐỊNH KÌ</h3><p style="font-size:11px">Các ô ghi mã câu và điểm; mức độ do giáo viên phân loại. Tỉ lệ tính theo điểm.</p><div style="overflow:auto"><table style="min-width:950px"><thead><tr><th rowspan="2">Chủ đề / Nội dung</th>${Object.values(types).map(t=>`<th colspan="3">${t}</th>`).join('')}<th rowspan="2">Điểm</th><th rowspan="2">Tỉ lệ</th></tr><tr>${Object.keys(types).map(()=>levels.map(l=>`<th>${l}</th>`).join('')).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.topic)}</td>${r.cells.map(c=>`<td>${esc(c||'–')}</td>`).join('')}<td>${r.total.toFixed(2)}</td><td>${sums().total?(r.total/sums().total*100).toFixed(1):0}%</td></tr>`).join('')}<tr><td>Tổng điểm</td>${Object.keys(types).flatMap(t=>levels.map(l=>`<td>${current.questions.filter(q=>q.type===t&&q.level===l).reduce((s,q)=>s+Number(q.points),0).toFixed(2)}</td>`)).join('')}<td>${sums().total.toFixed(2)}</td><td>100%</td></tr></tbody></table></div><p style="font-size:11px;margin-top:15px">${levels.map(l=>`${l}: ${sums().byLevel[l].toFixed(2)} điểm`).join(' · ')}</p>`}
function specHtml(){return `<h3>BẢN ĐẶC TẢ ĐỀ KIỂM TRA ĐỊNH KÌ</h3><div style="overflow:auto"><table><thead><tr><th>Câu</th><th>Chủ đề / Nội dung</th><th>Yêu cầu cần đạt</th><th>Dạng câu</th><th>Mức độ</th><th>Điểm</th></tr></thead><tbody>${orderedQuestions().map((q,i)=>`<tr><td>C${i+1}</td><td>${esc(q.topic)}</td><td>${esc(q.goal)}</td><td>${types[q.type]}</td><td>${q.level}</td><td>${Number(q.points).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p style="font-size:11px;margin-top:12px">Mỗi hàng tương ứng một câu; với đúng/sai, giáo viên mô tả yêu cầu của 4 ý trong cùng hàng và xác định mức độ tổng hợp phù hợp.</p>`}
function answersHtml(){return `<h3>ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM</h3>${orderedQuestions().map((q,i)=>`<p><b>Câu ${i+1} · ${Number(q.points).toFixed(2)} điểm · ${q.level}</b><br><span class="rubric">${esc(q.answer||'[Chưa nhập đáp án / hướng dẫn chấm]')}</span></p>`).join('')}<p style="font-size:12px">Câu đúng/sai: hướng dẫn chấm phải nêu đáp án cho từng ý a–d và quy tắc cho điểm được trường/Sở áp dụng. Không mặc định cách chấm của kỳ thi tốt nghiệp.</p>`}
function questionEditor(){return `<div class="panel"><div class="panel-title">Câu hỏi & phân loại</div><p class="help">Đáp án của câu nhập từ .doc chưa được suy đoán. Hãy đối chiếu bản gốc và nhập đáp án.</p>${current.questions.map((q,i)=>`<div class="bank-question"><div style="display:flex;justify-content:space-between"><b>Câu trong bản soạn #${i+1}</b><button onclick="deleteQuestion(${i})">Xóa ×</button></div><label class="help">Nội dung câu hỏi</label><textarea oninput="editQ(${i},'text',this.value)">${esc(q.text)}</textarea><div class="question-meta"><label>Dạng<select onchange="editQ(${i},'type',this.value)">${Object.entries(types).map(([k,t])=>`<option value="${k}" ${q.type===k?'selected':''}>${t}</option>`).join('')}</select></label><label>Mức độ<select onchange="editQ(${i},'level',this.value)">${levels.map(l=>`<option ${l===q.level?'selected':''}>${l}</option>`).join('')}</select></label><label>Điểm<input type="number" min="0.01" max="10" step="0.05" value="${q.points}" onchange="editQ(${i},'points',this.value)"></label></div><label class="help">Chủ đề / đơn vị kiến thức</label><input value="${esc(q.topic)}" oninput="editQ(${i},'topic',this.value)"><label class="help">Yêu cầu cần đạt / năng lực đánh giá</label><input value="${esc(q.goal)}" oninput="editQ(${i},'goal',this.value)"><label class="help">Phương án A–D hoặc 4 ý a–d (mỗi dòng một ý)</label><textarea oninput="editQ(${i},'options',this.value)">${esc(q.options)}</textarea><label class="help">Đáp án / các ý chấm kèm điểm</label><textarea oninput="editQ(${i},'answer',this.value)">${esc(q.answer)}</textarea></div>`).join('')}<button class="primary" onclick="addQuestion()">＋ Thêm câu hỏi</button> <button class="secondary" onclick="bankPicker()">Chọn từ ngân hàng</button></div>`}
function editQ(i,k,v){current.questions[i][k]=k==='points'?Math.max(.01,Math.min(10,Number(v)||.01)):v;persist();const s=sums();$('.stats').innerHTML=`<div class="stat"><strong>${current.questions.length}</strong>Câu hỏi</div><div class="stat"><strong>${s.total.toFixed(2)} / 10</strong>Tổng điểm</div><div class="stat"><strong>${checks().length} mục</strong>Cần rà soát</div>`}
function addQuestion(){current.questions.push({id:crypto.randomUUID(),type:'mc',level:'Biết',topic:current.meta.title,goal:'',text:'',options:'A. \nB. \nC. \nD. ',answer:'',points:.25});persist();examTab('questions')}
function deleteQuestion(i){current.questions.splice(i,1);persist();examTab('questions')}
function rulesEditor(){return `<div class="panel"><h3>Cấu hình mục tiêu theo điểm</h3><p class="help">Các tỉ lệ dưới đây là mục tiêu rà soát; không tự sửa điểm hoặc mức độ câu hỏi.</p><div class="notice">Khung 7991 tham khảo: 30 / 20 / 20 / 30. Môn không sử dụng trả lời ngắn chuyển toàn bộ điểm của dạng này sang đúng/sai: 30 / 40 / 0 / 30. Với THCS, chọn theo hướng dẫn Sở/trường.</div><div style="margin:20px 0"><button class="secondary" onclick="preset(false)">Khung đủ 4 dạng</button> <button class="secondary" onclick="preset(true)">Không trả lời ngắn</button></div><h3>Tỉ lệ dạng câu hỏi (%)</h3><div class="fieldrow">${Object.entries(types).map(([k,t])=>`<div class="field"><label>${t}</label><input type="number" min="0" max="100" value="${current.targets[k]}" onchange="setTarget('${k}',this.value)"></div>`).join('')}</div><h3>Tỉ lệ mức độ (%)</h3><div class="fieldrow">${levels.map((l,i)=>`<div class="field"><label>${l}</label><input type="number" min="0" max="100" value="${current.targets[['know','understand','apply'][i]]}" onchange="setTarget('${['know','understand','apply'][i]}',this.value)"></div>`).join('')}</div><p id="targetSums" class="help">${targetSumText()}</p></div>`}
function targetSumText(){return `Tổng tỉ lệ dạng câu: ${['mc','tf','short','essay'].reduce((s,k)=>s+current.targets[k],0)}% · Tổng mức độ: ${['know','understand','apply'].reduce((s,k)=>s+current.targets[k],0)}% (mỗi nhóm cần bằng 100%).`}
function setTarget(k,v){current.targets[k]=Math.max(0,Math.min(100,Number(v)||0));persist();$('#targetSums').textContent=targetSumText()}
function preset(noShort){Object.assign(current.targets,{mc:30,tf:noShort?40:20,short:noShort?0:20,essay:30,know:40,understand:30,apply:30});persist();examTab('rules')}
function bankPicker(){const banks=sources.filter(s=>s.type==='Ngân hàng câu hỏi');$('#modalBody').innerHTML='<h2>Nhập câu hỏi từ học liệu</h2><p class="help">Câu nhiều lựa chọn có đủ A–D được đưa vào bản soạn. Đáp án và phân loại cần giáo viên kiểm tra.</p>'+banks.map(s=>`<div class="sourcecard" style="margin-top:10px"><b>${esc(s.name)}</b><br><button class="secondary" onclick="importBank(${sources.indexOf(s)})">Thêm tối đa 12 câu</button></div>`).join('');$('#modal').showModal()}
function importBank(i){const q=parseQuestions(sources[i].text).slice(0,12);if(!q.length)return toast('Chưa nhận diện được câu có đủ A–D.');current.questions.push(...q);persist();$('#modal').close();examTab('questions');toast(`Đã thêm ${q.length} câu. Nhập đáp án và phân loại trước khi dùng.`)}
function library(){return heading('KHO HỌC LIỆU','Tư liệu tốt. Bài dạy hay.','Giáo án, bài giảng và câu hỏi bạn đã cung cấp — sẵn sàng để tham khảo.',`<button class="primary" onclick="$('#fileInput').click()">＋ Thêm học liệu</button>`)+`<input id="fileInput" type="file" multiple accept=".docx,.pptx,.txt,.json,.zip" hidden onchange="uploadFiles(this.files)"><div class="filterrow"><input id="search" placeholder="Tìm theo tên hoặc nội dung học liệu…" aria-label="Tìm học liệu"><select id="filter" aria-label="Loại học liệu"><option value="">Tất cả học liệu</option><option>Giáo án</option><option>Slide</option><option>Ngân hàng câu hỏi</option><option>Tư liệu</option></select></div><p class="help" style="margin-bottom:20px">Đã nhập nội dung từ các tệp bạn gửi. Thêm mới: DOCX, PPTX, TXT hoặc ZIP chứa DOCX/PPTX. DOC/PPT cũ cần lưu lại thành DOCX/PPTX trước khi tải mới.</p><div id="sourceGrid" class="library-grid"></div>`}
function bindLibrary(){$('#search').oninput=filterSources;$('#filter').onchange=filterSources;filterSources()}
function filterSources(){const term=$('#search').value.toLowerCase(),type=$('#filter').value;$('#sourceGrid').innerHTML=sources.map((s,i)=>({s,i})).filter(({s})=>(!type||s.type===type)&&(s.name+' '+s.text).toLowerCase().includes(term)).map(({s,i})=>`<article class="sourcecard"><span class="tag">${s.type} · Lớp ${esc(s.grade)}</span><h3>${esc(s.name)}</h3><small>${s.text.length.toLocaleString('vi-VN')} ký tự · Nội dung đã trích xuất</small><br><button class="secondary" onclick="viewSource(${i})">Xem học liệu ↗</button></article>`).join('')||'<div class="empty">Không có học liệu phù hợp.</div>'}
function viewSource(i){const s=sources[i];$('#modalBody').innerHTML=`<span class="eyebrow">${s.type} · LỚP ${esc(s.grade)}</span><h2 style="margin:10px 0">${esc(s.name)}</h2><div class="modal-actions"><button class="primary" onclick="useSource(${i},'plan')">Dùng soạn giáo án</button><button class="secondary" onclick="useSource(${i},'slides')">Dùng tạo slide</button><button class="secondary" onclick="useSource(${i},'exam')">Dùng tạo đề</button></div><pre>${esc(s.text)}</pre>`;$('#modal').showModal()}
function useSource(i,k){draft.source=String(i);$('#modal').close();go(k);applySource()}
async function uploadFiles(files){let count=0;const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main',an='http://schemas.openxmlformats.org/drawingml/2006/main';async function readFile(name,buffer){const ext=name.split('.').pop().toLowerCase();let text='';if(ext==='txt')text=new TextDecoder().decode(buffer);else if(ext==='docx'||ext==='pptx'){const z=await JSZip.loadAsync(buffer);let paths=ext==='docx'?['word/document.xml']:Object.keys(z.files).filter(p=>/^ppt\/slides\/slide\d+\.xml$/.test(p)).sort((a,b)=>Number(a.match(/slide(\d+)/)[1])-Number(b.match(/slide(\d+)/)[1]));for(const path of paths){const f=z.file(path);if(!f)continue;const d=new DOMParser().parseFromString(await f.async('string'),'application/xml');text+=Array.from(d.getElementsByTagNameNS(ext==='docx'?ns:an,'p')).map(p=>Array.from(p.getElementsByTagNameNS(ext==='docx'?ns:an,'t')).map(t=>t.textContent).join('')).join('\n')+'\n'}}else if(ext==='zip'){const z=await JSZip.loadAsync(buffer);if(Object.keys(z.files).length>200)throw Error('ZIP quá nhiều mục (tối đa 200).');for(const [p,f] of Object.entries(z.files)){if(!f.dir&&/\.(docx|pptx|txt)$/i.test(p))await readFile(p,await f.async('arraybuffer'))}return}else if(ext==='json'){const d=JSON.parse(new TextDecoder().decode(buffer));if(d.kind&&d.meta){validateProject(d);current=d;kind=d.kind;draft={...draft,...d.meta};persist();count++;return}else throw Error('JSON không phải bản sao dự án.')}else throw Error('Định dạng chưa hỗ trợ: '+ext);if(text.length>1000000)throw Error('Học liệu vượt 1 triệu ký tự.');if(!text.trim())throw Error('Không đọc được văn bản trong '+name);sources.push({name,type:ext==='pptx'?'Slide':ext==='docx'?'Giáo án':'Tư liệu',grade:draft.grade,text,user:true});count++}
try{for(const f of files){if(f.size>30*1024*1024)throw Error('Tệp vượt 30 MB.');await readFile(f.name,await f.arrayBuffer())}localStorage.setItem('ga-user-sources',JSON.stringify(sources.filter(s=>s.user)));$('#sourceCount').textContent=sources.length;render();toast(`Đã nhập ${count} học liệu / dự án.`)}catch(e){render();toast('Không nhập được: '+e.message)}}
function validateProject(d){if(!['plan','slides','exam'].includes(d.kind)||typeof d.meta.title!=='string')throw Error('Dự án không hợp lệ');if(d.kind==='plan'&&!Array.isArray(d.sections))throw Error('Thiếu các phần giáo án');if(d.kind==='slides'&&(!Array.isArray(d.slides)||!d.slides.length))throw Error('Thiếu slide');if(d.kind==='exam'&&(!Array.isArray(d.questions)||!d.targets))throw Error('Thiếu câu hỏi/cấu hình');}
function saveCurrent(){if(!current||current.kind!==kind)return toast('Hãy tạo bản nháp trước.');current.updated=new Date().toISOString();const i=saved.findIndex(x=>x.id===current.id);if(i>=0)saved[i]=structuredClone(current);else saved.unshift(structuredClone(current));persist();toast('Đã lưu bản nháp trên trình duyệt này.');}
function savedView(){return heading('KHÔNG GIAN CÁ NHÂN','Bài soạn của bạn','Mở lại, tải bản sao hoặc xuất bản nội dung đã hoàn thiện.')+`<div class="notice" style="margin:0 0 20px">Bản soạn được lưu trên trình duyệt này. Tải bản sao JSON để chuyển máy hoặc tránh mất dữ liệu khi xóa bộ nhớ trình duyệt.</div><div class="tablewrap"><table><thead><tr><th>TÊN BẢN SOẠN</th><th>LOẠI</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${saved.length?saved.map((s,i)=>`<tr><td class="filename">${esc(s.meta.title)}<br><small style="color:#88937f">${new Date(s.updated||s.created).toLocaleDateString('vi-VN')} · Lớp ${esc(s.meta.grade)}</small></td><td>${names[s.kind]}</td><td><span class="tag">${s.status==='Đã xuất HTML'?'Đã xuất HTML':'Bản nháp'}</span></td><td><button onclick="openSaved(${i})">Mở</button> · <button onclick="backupSaved(${i})">JSON ↓</button> · <button onclick="deleteSaved(${i})">Xóa</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">Chưa có bản soạn đã lưu. Tạo bản nháp và nhấn “Lưu bản nháp”.</td></tr>'}</tbody></table></div>`}
function openSaved(i){current=structuredClone(saved[i]);draft={...draft,...current.meta};slideIndex=0;tab='exam';persist();go(current.kind)}function backupSaved(i){download(JSON.stringify(saved[i],null,2),'ban-soan.json','application/json')}function deleteSaved(i){if(confirm('Xóa bản soạn đã lưu này?')){saved.splice(i,1);persist();render()}}
function guide(){return heading('CĂN CỨ & CÁCH SỬ DỤNG','Soạn đúng. Duyệt kỹ. Dạy tốt.','Hiểu phạm vi của từng văn bản và cách làm việc trong Studio.')+`<article class="panel guide"><h3>1. Công văn 7991 áp dụng cho phần nào?</h3><p>Công văn 7991/BGDĐT-GDTrH ngày 17/12/2024 hướng dẫn kiểm tra, đánh giá đối với cấp THCS, THPT. Đoạn yêu cầu xây dựng ma trận, bản đặc tả, đề và hướng dẫn chấm trong văn bản nói đến cơ sở giáo dục cấp THPT, dưới hướng dẫn của Sở GDĐT. Không nên coi phụ lục là một tỉ lệ bắt buộc duy nhất cho mọi đề THCS.</p><p>Phụ lục tham khảo phân bổ điểm khoảng 30% nhiều lựa chọn, 20% đúng/sai, 20% trả lời ngắn, 30% tự luận; Biết 40%, Hiểu 30%, Vận dụng 30%. Câu đúng/sai có 4 ý. Môn không dùng trả lời ngắn chuyển toàn bộ điểm của dạng này sang đúng/sai.</p><p>Với Lịch sử THCS: chọn cấu hình theo văn bản địa phương, thời điểm kiểm tra và phạm vi kiến thức đã học. Mặc định Studio dùng 30 / 40 / 0 / 30 làm khung tham khảo có thể sửa.</p><p><a target="_blank" rel="noopener" href="https://cdn.thuvienphapluat.vn/uploads/Hoidapphapluat/2024/NTH/20122024/20241210-Cong-van-7991-huong-dan-KTDGDK.pdf">Đọc bản Công văn 7991 và phụ lục ↗</a></p><h3>2. Giáo án và slide</h3><p>Khung giáo án: mục tiêu; thiết bị và học liệu; tiến trình gồm mở đầu, hình thành kiến thức, luyện tập và vận dụng. Trong mỗi hoạt động có mục tiêu, nội dung, sản phẩm và tổ chức thực hiện, theo cấu trúc 5512 được thể hiện trong các giáo án bạn cung cấp.</p><p>7991 không quy định mẫu giáo án hoặc slide. Slide là phương tiện hỗ trợ hoạt động học. Các lựa chọn tích hợp năng lực số, AI và quốc phòng chỉ thêm nhiệm vụ để giáo viên chỉnh cho phù hợp; không tự gán mã năng lực pháp lý.</p><h3>3. Quy trình làm việc</h3><ol><li>Chọn học liệu hoặc nhập yêu cầu cần đạt và nội dung.</li><li>Tạo bản nháp bằng khung mẫu; sửa từng phần hoặc từng slide.</li><li>Với đề kiểm tra: nhập câu, 4 phương án/4 ý nếu có, đáp án, điểm, chủ đề và mức độ.</li><li>Kiểm tra ma trận và đặc tả; đối chiếu tổng điểm và tỉ lệ.</li><li>Lưu bản nháp, xuất Word/PowerPoint; chọn PDF/In để lưu PDF từ hộp thoại in.</li><li>Xuất bản HTML tạo tệp độc lập để gửi cho người khác. Với đề, tệp dành cho học sinh không chứa đáp án.</li></ol><h3>4. Khả năng hiện tại</h3><p>Studio chạy trong trình duyệt, tạo bằng khung mẫu và học liệu đầu vào. Chưa có dịch vụ AI sinh nội dung, đồng bộ đa thiết bị hay đường dẫn công khai riêng cho từng bài. Không tự xác nhận câu hỏi “đạt chuẩn” chỉ vì tổng điểm khớp.</p><p>Tài liệu DOC/PPT đã gửi được trích xuất nội dung văn bản; bố cục, hình ảnh và định dạng gốc chưa được tái tạo. DOCX/PPTX mới tải lên cũng chỉ nhập phần văn bản.</p><p>Word và PowerPoint là tệp thật có thể chỉnh sửa. PDF dùng chức năng in của trình duyệt. Bản sao JSON giữ đầy đủ dữ liệu bài soạn.</p></article>`}
function download(data,name,type){const b=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function ensureCurrent(){if(!current||current.kind!==kind){toast('Hãy tạo bản nháp trước.');return false}return true}
function safeName(){return (current.meta.title||'bai-soan').replace(/[\\/:*?"<>|]/g,'-').slice(0,100)}
async function exportWord(){if(!ensureCurrent())return;try{const D=docx;const children=[];function p(text,bold=false,size=24){return new D.Paragraph({children:[new D.TextRun({text,bold,size,font:'Times New Roman'})],spacing:{after:140}})}function textLines(t){for(const line of paragraphs(t))children.push(p(line))}function table(rows){return new D.Table({width:{size:100,type:D.WidthType.PERCENTAGE},rows:rows.map((row,i)=>new D.TableRow({children:row.map(text=>new D.TableCell({children:[p(String(text),i===0,18)]}))}))})}children.push(p(current.meta.title,true,30));textLines(`${current.meta.school}\nMôn ${current.meta.subject} ${current.meta.grade} · ${current.meta.book}\nGiáo viên: ${current.meta.teacher||'................................'}`);if(current.kind==='plan'){current.sections.forEach(s=>{children.push(p(s.title,true));textLines(s.text)})}else{children.push(p('ĐỀ KIỂM TRA · '+current.meta.minutes+' phút',true));textLines('Họ và tên: ....................................... Lớp: ............');let n=0;Object.keys(types).forEach(t=>{const qs=orderedQuestions().filter(q=>q.type===t);if(!qs.length)return;children.push(p(types[t].toUpperCase(),true));qs.forEach(q=>{textLines(`Câu ${++n} (${Number(q.points).toFixed(2)} điểm). ${q.text}\n${q.options}`)})});children.push(new D.Paragraph({pageBreakBefore:true,children:[new D.TextRun({text:'MA TRẬN',bold:true,size:26})]}));const rows=matrixRows();children.push(table([['Chủ đề',...Object.keys(types).flatMap(t=>levels.map(l=>types[t]+' / '+l)),'Điểm'],...rows.map(r=>[r.topic,...r.cells,r.total.toFixed(2)])]));children.push(p('BẢN ĐẶC TẢ',true));children.push(table([['Câu','Chủ đề','Yêu cầu cần đạt','Dạng','Mức độ','Điểm'],...orderedQuestions().map((q,i)=>['C'+(i+1),q.topic,q.goal,types[q.type],q.level,q.points])]));children.push(p('ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM',true));orderedQuestions().forEach((q,i)=>textLines(`Câu ${i+1} (${q.points} điểm): ${q.answer||'[Chưa nhập đáp án/hướng dẫn chấm]'}`));if(checks().length){children.push(p('CẦN RÀ SOÁT TRƯỚC KHI SỬ DỤNG',true));textLines(checks().join('\n'))}}
const doc=new D.Document({sections:[{properties:{page:{size:{orientation:current.kind==='exam'?D.PageOrientation.LANDSCAPE:D.PageOrientation.PORTRAIT},margin:{top:1000,bottom:1000,left:1000,right:1000}}},children}]});download(await D.Packer.toBlob(doc),safeName()+'.docx');toast('Đã xuất Word: bản nháp để giáo viên duyệt.')}catch(e){toast('Không xuất được Word: '+e.message)}}
async function exportPptx(){if(!ensureCurrent())return;try{const ppt=new pptxgen();ppt.layout='LAYOUT_WIDE';ppt.author=current.meta.teacher||'Giáo Án Studio';ppt.subject=current.meta.subject;ppt.title=current.meta.title;ppt.lang='vi-VN';current.slides.forEach((s,i)=>{const sl=ppt.addSlide();sl.background={color:'EAF0DF'};sl.addText(`${current.meta.subject.toUpperCase()} ${current.meta.grade} · BÀI GIẢNG`,{x:.65,y:.35,w:11,h:.3,fontSize:10,color:'678052',fontFace:'Arial'});sl.addText(s.title,{x:.65,y:1,w:11.8,h:1.25,fontSize:30,color:'233B36',fontFace:'Georgia',bold:false,breakLine:false,fit:'shrink'});sl.addText(paragraphs(s.text).map(t=>({text:t,options:{bullet:{indent:18},breakLine:true}})),{x:.8,y:2.5,w:11.6,h:3.85,fontSize:20,color:'314B3D',fontFace:'Arial',paraSpaceAfterPt:13,fit:'shrink'});sl.addText(`${i+1} / ${current.slides.length}`,{x:11.5,y:6.85,w:1,h:.25,fontSize:10,color:'678052',align:'right'});sl.addNotes(s.note||'')});await ppt.writeFile({fileName:safeName()+'.pptx'});toast('Đã xuất PowerPoint có ghi chú giảng dạy.')}catch(e){toast('Không xuất được PowerPoint: '+e.message)}}
function standalone(content,title,slides=false){return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:16px/1.75 Georgia,'Times New Roman',serif;color:#243b30;max-width:1000px;margin:40px auto;padding:20px}h2{text-align:center}h3{margin-top:30px}table{border-collapse:collapse;width:100%;font:11px/1.5 Arial}td,th{border:1px solid #ddd;padding:8px;text-align:left}th{background:#eef3e8}.meta{text-align:center;font-size:13px}button{background:#296c57;color:white;border:0;border-radius:5px;padding:10px 15px;cursor:pointer}.slide{page-break-after:always;aspect-ratio:16/9;background:#eaf0df;padding:35px;margin:20px 0;box-sizing:border-box}.slide h2{text-align:left;font-size:28px}.slide p{white-space:pre-wrap}.notes{font:12px Arial;color:#777}@media print{button,.notes{display:none}body{margin:0;padding:0;max-width:none}.slide{margin:0}tr{break-inside:avoid}}</style></head><body><button onclick="window.print()">In / Lưu PDF</button>${content}<p class="notes">Bản xuất từ Giáo Án Studio. Nội dung do giáo viên biên soạn và duyệt.</p></body></html>`}
function artifactHtml(){if(current.kind==='plan')return metaHtml()+current.sections.map(s=>`<h3>${esc(s.title)}</h3><p style="white-space:pre-wrap">${esc(s.text)}</p>`).join('');if(current.kind==='slides')return current.slides.map((s,i)=>`<section class="slide"><span>${esc(current.meta.subject)} ${esc(current.meta.grade)} · ${i+1}/${current.slides.length}</span><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p></section>`).join('');return metaHtml()+examHtml(false)}
function printCurrent(){if(!ensureCurrent())return;const blob=new Blob([standalone(artifactHtml(),current.meta.title)],{type:'text/html'});const u=URL.createObjectURL(blob);const w=window.open(u,'_blank');if(!w){URL.revokeObjectURL(u);toast('Cho phép mở tab mới để in, hoặc xuất HTML rồi mở tệp.');return}w.onload=()=>w.print();setTimeout(()=>URL.revokeObjectURL(u),60000)}
function publishCurrent(){if(!ensureCurrent())return;if(current.kind==='exam'){const required=current.questions.filter(q=>!q.text.trim()||!q.answer.trim()||!q.goal.trim());if(required.length){toast('Điền nội dung, đáp án và yêu cầu cần đạt cho mọi câu trước khi xuất bản.');examTab('questions');return}if(checks().length){toast('Hoàn thiện các mục rà soát trước khi xuất bản đề.');return}}download(standalone(artifactHtml(),current.meta.title),safeName()+'.html','text/html');current.status='Đã xuất HTML';saveCurrent();toast('Đã xuất HTML độc lập để chia sẻ. Đề học sinh không kèm đáp án.');}
fetch('sources.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(s=>{sources=s;try{sources.push(...JSON.parse(localStorage.getItem('ga-user-sources')||'[]'))}catch(e){}$('#sourceCount').textContent=sources.length;go(location.hash.slice(1)||'home')}).catch(()=>{render();toast('Chưa tải được học liệu. Tải lại trang để thử lại.')});
function loadExampleExam(){kind='exam';const title='Nước Mỹ và Tây Âu từ năm 1945 đến năm 1991';current={id:crypto.randomUUID(),kind,meta:{...draft,title,subject:'Lịch sử',grade:'9',minutes:'45'},created:new Date().toISOString(),status:'Bản nháp',sourceName:'Giáo án Bài 11 tiết 1 và tiết 2 trong 99.zip',targets:{mc:30,tf:40,short:0,essay:30,know:40,understand:30,apply:30},questions:[]};const add=(type,level,topic,text,options,answer,points,goal)=>current.questions.push({id:crypto.randomUUID(),type,level,topic,text,options,answer,points,goal});const qs=[['Hai đảng thay nhau cầm quyền ở Mỹ là','Đảng Dân chủ và Đảng Cộng hòa','Đảng Lao động và Đảng Bảo thủ','Đảng Xã hội và Đảng Tự do','Đảng Dân chủ và Đảng Lao động'],['Khối quân sự NATO được thành lập năm nào?','1945','1957','1949','1973'],['NATO có tên đầy đủ là','Cộng đồng Kinh tế châu Âu','Tổ chức Hiệp ước Bắc Đại Tây Dương','Liên minh châu Âu','Cộng đồng Than – Thép châu Âu'],['Mỹ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh năm nào?','1973','1951','1949','1989'],['Kế hoạch Mác-san có vai trò nào đối với kinh tế Tây Âu sau chiến tranh?','Hỗ trợ khôi phục kinh tế','Chấm dứt mọi quan hệ với Mỹ','Xóa bỏ sản xuất công nghiệp','Thay thế toàn bộ lao động bằng máy móc'],['Cộng đồng Than – Thép châu Âu ra đời năm nào?','1957','1951','1949','1973'],['Cộng đồng Kinh tế châu Âu (EEC) ra đời năm nào?','1945','1950','1957','1991'],['Trong giai đoạn 1950–1973, Tây Âu trở thành','Khu vực không có hoạt động tài chính','Khu vực phụ thuộc hoàn toàn vào nông nghiệp','Khu vực không tham gia thương mại','Một trong ba trung tâm kinh tế – tài chính thế giới'],['Ba trung tâm kinh tế – tài chính lớn được nhắc đến trong bài học là','Mỹ, Tây Âu, Nhật Bản','Mỹ, Tây Âu, châu Phi','Tây Âu, Nhật Bản, châu Phi','Mỹ, Nhật Bản, Nam Mỹ'],['Chiến lược toàn cầu của Mỹ có mục tiêu nào sau đây?','Xóa bỏ mọi liên minh quân sự','Thực hiện tham vọng bá chủ thế giới','Ngừng can thiệp vào các khu vực','Chấm dứt chạy đua vũ trang ngay năm 1945'],['Tây Âu chịu tác động của khủng hoảng năng lượng từ năm nào?','1951','1957','1973','1949'],['Mỹ cải thiện quan hệ với Liên Xô và Trung Quốc từ','Thập niên 1940','Thập niên 1950','Thập niên 1960','Thập niên 1970']];const answers=['A','C','B','D','A','B','C','D','A','B','C','D'];qs.forEach((q,i)=>add('mc','Biết',i<4||i===9||i===11?'Nước Mỹ':'Tây Âu',q[0],q.slice(1).map((v,j)=>'ABCD'[j]+'. '+v).join('\n'),answers[i]+'. '+q[answers[i].charCodeAt(0)-64],.25,'Nêu được nét chính về chính trị, kinh tế Mỹ và Tây Âu hoặc nhận biết mốc liên kết khu vực.'));
add('tf','Biết','Mỹ và Tây Âu','Xác định đúng/sai với các nhận định sau.','a. NATO được thành lập năm 1949.\nb. EEC được thành lập năm 1951.\nc. Cộng đồng Than – Thép châu Âu ra đời năm 1951.\nd. Mỹ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh năm 1989.','a Đúng; b Sai (EEC ra đời năm 1957); c Đúng; d Đúng. Mỗi ý đúng 0,25 điểm.',1,'Nhận biết mốc chính trị và liên kết khu vực.');
add('tf','Hiểu','Nước Mỹ','Dựa vào biến động vị thế kinh tế Mỹ, đánh giá các nhận định.','a. Tỉ trọng kinh tế giảm đồng nghĩa quy mô kinh tế luôn giảm.\nb. Cạnh tranh từ Tây Âu và Nhật Bản góp phần làm ưu thế tương đối của Mỹ suy giảm.\nc. Chi phí quân sự lớn có thể gây sức ép cho nền kinh tế Mỹ.\nd. Tỉ trọng suy giảm tự nó chứng minh Mỹ không còn là cường quốc kinh tế.','a Sai; b Đúng; c Đúng; d Sai. Mỗi ý đúng 0,25 điểm. Phân biệt tỉ trọng tương đối và quy mô tuyệt đối.',1,'Giải thích nguyên nhân và ý nghĩa sự suy giảm ưu thế tương đối của kinh tế Mỹ.');
add('tf','Hiểu','Tây Âu','Đánh giá các nhận định về phục hồi kinh tế Tây Âu.','a. Viện trợ theo Kế hoạch Mác-san góp phần khôi phục kinh tế Tây Âu.\nb. Nhận viện trợ Mỹ khiến Tây Âu hoàn toàn không còn chịu ảnh hưởng từ Mỹ.\nc. Phục hồi sau chiến tranh là cơ sở cho phát triển kinh tế ở giai đoạn sau.\nd. Khủng hoảng năng lượng năm 1973 tạo điều kiện để kinh tế Tây Âu tăng trưởng nhanh hơn ngay lập tức.','a Đúng; b Sai; c Đúng; d Sai. Mỗi ý đúng 0,25 điểm.',1,'Giải thích sự phục hồi và biến động kinh tế Tây Âu.');
add('tf','Hiểu','Tây Âu','Đánh giá các nhận định về liên kết khu vực.','a. Liên kết kinh tế có thể tạo điều kiện mở rộng thị trường.\nb. Hợp tác khu vực khiến mỗi nước không cần quan tâm lợi ích quốc gia.\nc. Liên kết góp phần tăng sức cạnh tranh của các nước tham gia.\nd. Liên kết khu vực đồng nghĩa các nước không còn bất kỳ khác biệt nào.','a Đúng; b Sai; c Đúng; d Sai. Mỗi ý đúng 0,25 điểm.',1,'Giải thích ý nghĩa của quá trình liên kết kinh tế ở Tây Âu.');
add('essay','Vận dụng','Tây Âu','Từ quá trình liên kết khu vực ở Tây Âu, rút ra một bài học cho Việt Nam trong hội nhập quốc tế và giải thích bằng lập luận phù hợp.','','Nêu bài học phù hợp, ví dụ chủ động hợp tác đi đôi với bảo vệ lợi ích quốc gia (0,5 điểm); liên hệ đúng nội dung liên kết Tây Âu (0,5 điểm); giải thích thuyết phục, có ví dụ phù hợp (0,5 điểm). Chấp nhận phương án tương đương có căn cứ.',1.5,'Vận dụng hiểu biết về liên kết khu vực để rút ra bài học hội nhập.');
add('essay','Vận dụng','Nước Mỹ','Một bạn cho rằng: “Tỉ trọng GDP giảm chứng tỏ một nước chắc chắn trở nên nghèo hơn”. Dựa trên bài học về kinh tế Mỹ, hãy phản biện nhận định này.','','Phân biệt tỉ trọng và quy mô kinh tế tuyệt đối (0,5 điểm); dùng dẫn chứng Mỹ vẫn là cường quốc kinh tế dù ưu thế tương đối suy giảm (0,5 điểm); lập luận: các nước khác tăng nhanh hơn có thể khiến tỉ trọng giảm, cần thêm dữ liệu trước khi kết luận mức sống (0,5 điểm).',1.5,'Vận dụng kiến thức để đánh giá nhận định về tỉ trọng và quy mô kinh tế.');draft={...draft,...current.meta};tab='exam';persist();render();toast('Đã tải đề minh họa 10 điểm. Giáo viên cần duyệt trước khi sử dụng.');}
